import{_ as s,o as a,c as n,a4 as e}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"MyBilibili 终极架构：从嵌入式到云","description":"","frontmatter":{"title":"MyBilibili 终极架构：从嵌入式到云","date":"2026-08-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/13-ultimate-architecture.md","filePath":"posts/13-ultimate-architecture.md"}'),d={name:"posts/13-ultimate-architecture.md"};function r(i,t,o,l,p,h){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="mybilibili-终极架构-从嵌入式到云" tabindex="-1">MyBilibili 终极架构：从嵌入式到云 <a class="header-anchor" href="#mybilibili-终极架构-从嵌入式到云" aria-label="Permalink to &quot;MyBilibili 终极架构：从嵌入式到云&quot;">​</a></h1><h2 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h2><blockquote><p>一个 Spring Cloud Alibaba 的 Java 微服务项目，重构为 Go + Traefik + gRPC + etcd + NATS 云原生架构，<strong>同一套代码可以从 ARM 盒子跑到 K8s 集群</strong>，内存从 2GB 降到 600MB，启动从 80 秒降到 400 毫秒，月费从 7000 元降到 100 元电费。</p></blockquote><hr><h2 id="_1-架构全景" tabindex="-1">1. 架构全景 <a class="header-anchor" href="#_1-架构全景" aria-label="Permalink to &quot;1. 架构全景&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        用户入口（域名 + HTTPS）                        │</span></span>
<span class="line"><span>│              Traefik（K8s Gateway API 实现，自动 Let&#39;s Encrypt）       │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                                      │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────┐  ┌──────────┐  ┌──────────┐  ┌───────┐ │</span></span>
<span class="line"><span>│  │  Gateway  │  │   Core   │  │ Realtime │  │  Search  │  │  Ads  │ │</span></span>
<span class="line"><span>│  │  路由/限流 │  │ CRUD 业务 │  │ WebSocket│  │  Bleve   │  │ 计数  │ │</span></span>
<span class="line"><span>│  │  JWT 验签 │  │ MySQL 操作│  │ NATS 广播│  │ 嵌入式   │  │       │ │</span></span>
<span class="line"><span>│  └──────────┘  └──────────┘  └──────────┘  └──────────┘  └───────┘ │</span></span>
<span class="line"><span>│                                                                      │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │                     gRPC（HTTP/2 + Protobuf）                     │ │</span></span>
<span class="line"><span>│  │              etcd（服务发现） + NATS（消息队列）                     │ │</span></span>
<span class="line"><span>│  └─────────────────────────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                                      │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────┐  ┌──────────┐  ┌──────────────────────┐ │</span></span>
<span class="line"><span>│  │  MySQL   │  │  Redis   │  │  MinIO   │  │  Media（RX580 硬编码）│ │</span></span>
<span class="line"><span>│  │  主库    │  │  缓存    │  │  对象存储 │  │  Store（支付事务）    │ │</span></span>
<span class="line"><span>│  └──────────┘  └──────────┘  └──────────┘  └──────────────────────┘ │</span></span>
<span class="line"><span>│                                                                      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                     可观测性（全链路）                                 │</span></span>
<span class="line"><span>│     Prometheus（指标） + Loki（日志） + OpenTelemetry（链路追踪）       │</span></span>
<span class="line"><span>│                            Grafana（面板）                            │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                   CI/CD：GitHub Actions 多架构编译                     │</span></span>
<span class="line"><span>│         git push → 自动编译 arm64 + amd64 → 自动部署到 12 台设备        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_2-核心技术栈" tabindex="-1">2. 核心技术栈 <a class="header-anchor" href="#_2-核心技术栈" aria-label="Permalink to &quot;2. 核心技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>组件</th><th>标准</th><th>说人话</th></tr></thead><tbody><tr><td><strong>网关</strong></td><td>Traefik</td><td>K8s Gateway API 官方实现</td><td>55k stars，CNCF 项目</td></tr><tr><td><strong>服务发现</strong></td><td>etcd</td><td>K8s 底层存储</td><td>云原生标配</td></tr><tr><td><strong>RPC</strong></td><td>gRPC</td><td>CNCF 毕业项目</td><td>Google 出品，性能碾压 REST</td></tr><tr><td><strong>消息队列</strong></td><td>NATS</td><td>CNCF 孵化项目</td><td>Go 原生，~20MB，亚毫秒延迟</td></tr><tr><td><strong>缓存</strong></td><td>Redis</td><td>事实标准</td><td>没什么好说的</td></tr><tr><td><strong>数据库</strong></td><td>MySQL</td><td>事实标准</td><td>支付强一致</td></tr><tr><td><strong>本地存储</strong></td><td>SQLite</td><td>嵌入式标准</td><td>零依赖，单文件</td></tr><tr><td><strong>对象存储</strong></td><td>MinIO</td><td>S3 兼容标准</td><td>可无缝切云 OSS</td></tr><tr><td><strong>搜索</strong></td><td>Bleve</td><td>Go 嵌入式</td><td>零部署，嵌入二进制</td></tr><tr><td><strong>监控</strong></td><td>Prometheus</td><td>CNCF 毕业项目</td><td>云原生监控标准</td></tr><tr><td><strong>日志</strong></td><td>Loki</td><td>CNCF 毕业项目</td><td>轻量，与 Prometheus 同标签</td></tr><tr><td><strong>链路追踪</strong></td><td>OpenTelemetry</td><td>CNCF 毕业项目</td><td>遥测标准 API</td></tr><tr><td><strong>可视化</strong></td><td>Grafana</td><td>事实标准</td><td>面板一开，面试官闭嘴</td></tr></tbody></table><hr><h2 id="_3-部署模式-从嵌入式到云" tabindex="-1">3. 部署模式（从嵌入式到云） <a class="header-anchor" href="#_3-部署模式-从嵌入式到云" aria-label="Permalink to &quot;3. 部署模式（从嵌入式到云）&quot;">​</a></h2><h3 id="模式-a-嵌入式-12-台设备集群-—-最装逼" tabindex="-1">模式 A：嵌入式（12 台设备集群）— 最装逼 <a class="header-anchor" href="#模式-a-嵌入式-12-台设备集群-—-最装逼" aria-label="Permalink to &quot;模式 A：嵌入式（12 台设备集群）— 最装逼&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>老电脑（2核/4GB）: MySQL + Redis + etcd + NATS        ← 有状态基础设施</span></span>
<span class="line"><span>盒子 ×4（4核/1GB）: Traefik + Go 业务（gateway/core/realtime/ads/search）</span></span>
<span class="line"><span>手机 ×6（8核）: 搜索分片 / 冗余 / 开发测试</span></span>
<span class="line"><span>主力机（12核/RX580）: Media（硬编码）+ Store（支付）</span></span></code></pre></div><p><strong>78 核总算力，月费 100 元电费，云服务器同等配置约 20000 元/月。</strong></p><h3 id="模式-b-工作站-单机-—-最实用" tabindex="-1">模式 B：工作站（单机）— 最实用 <a class="header-anchor" href="#模式-b-工作站-单机-—-最实用" aria-label="Permalink to &quot;模式 B：工作站（单机）— 最实用&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>E5 X99（18核/64GB/RX580）: Docker Compose 全部服务</span></span></code></pre></div><p><strong>一台机器搞定，开发调试方便，架构不变。</strong></p><h3 id="模式-c-云原生-k8s-集群-—-最企业级" tabindex="-1">模式 C：云原生（K8s 集群）— 最企业级 <a class="header-anchor" href="#模式-c-云原生-k8s-集群-—-最企业级" aria-label="Permalink to &quot;模式 C：云原生（K8s 集群）— 最企业级&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>K8s 集群（任意云）: 将所有 Docker 容器换为 K8s Deployment，配置不变，代码不变</span></span></code></pre></div><hr><h2 id="_4-性能对比-硬数据" tabindex="-1">4. 性能对比（硬数据） <a class="header-anchor" href="#_4-性能对比-硬数据" aria-label="Permalink to &quot;4. 性能对比（硬数据）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>旧（Java Spring Cloud）</th><th>新（Go 云原生）</th><th>提升</th></tr></thead><tbody><tr><td>启动时间</td><td>8 服务 × 10s = <strong>80s</strong></td><td>8 服务 × 50ms = <strong>400ms</strong></td><td><strong>200 倍</strong></td></tr><tr><td>运行时内存</td><td>8 服务 × 300MB = <strong>2.4GB</strong></td><td>8 服务 × 30MB = <strong>240MB</strong></td><td><strong>10 倍</strong></td></tr><tr><td>部署体积</td><td>8 JAR × 50MB + JRE 300MB = <strong>700MB</strong></td><td>8 二进制 × 15MB = <strong>120MB</strong></td><td><strong>6 倍</strong></td></tr><tr><td>单机 QPS</td><td>500（JVM 预热后）</td><td>5000（起步即峰值）</td><td><strong>10 倍</strong></td></tr><tr><td>服务器月费</td><td>云服务器 ≈ <strong>7000 元</strong></td><td>自有设备 ≈ <strong>100 元电费</strong></td><td><strong>70 倍</strong></td></tr></tbody></table><hr><h2 id="_5-面试话术-三句话背熟" tabindex="-1">5. 面试话术（三句话背熟） <a class="header-anchor" href="#_5-面试话术-三句话背熟" aria-label="Permalink to &quot;5. 面试话术（三句话背熟）&quot;">​</a></h2><blockquote><p><strong>第一句（项目背景）：</strong> &quot;我主导了一个 Spring Cloud Alibaba 微服务项目的重构，将其从 Java 全栈迁移为 Go + Traefik + gRPC + etcd + NATS 的云原生架构，涉及 500+ Java 文件的重写。&quot;</p></blockquote><blockquote><p><strong>第二句（技术深度）：</strong> &quot;采用 K8s Gateway API 标准网关，gRPC 服务间通信，etcd 服务发现，NATS 消息队列，Prometheus/Loki/OpenTelemetry 全链路可观测性，GitHub Actions 多架构 CI/CD。同一套代码可以从 ARM 盒子跑到 K8s 集群。&quot;</p></blockquote><blockquote><p><strong>第三句（数据成果）：</strong> &quot;内存占用从 2GB 降到 240MB，启动从 80 秒降到 400 毫秒，部署从 8 个 JAR 变成 1 个 scp 命令。部署在自有 12 台设备集群上，78 核总算力，月费 100 元电费，同等云配置约 20000 元/月。&quot;</p></blockquote><hr><h2 id="_6-演示准备-让面试官拿出手机" tabindex="-1">6. 演示准备（让面试官拿出手机） <a class="header-anchor" href="#_6-演示准备-让面试官拿出手机" aria-label="Permalink to &quot;6. 演示准备（让面试官拿出手机）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>演示项</th><th>内容</th><th>链接</th></tr></thead><tbody><tr><td><strong>在线演示</strong></td><td>小程序/网页能直接打开</td><td>mybilibili.xxx</td></tr><tr><td><strong>Grafana 面板</strong></td><td>实时 CPU/内存/QPS/QPS 集群监控</td><td>mybilibili.xxx/grafana</td></tr><tr><td><strong>GitHub 仓库</strong></td><td>代码 + Actions CI/CD 徽章</td><td>github.com/chentianxiong123/mybilibili</td></tr><tr><td><strong>架构图</strong></td><td>一张图讲清楚全部</td><td>docs/ 目录</td></tr><tr><td><strong>对比报告</strong></td><td>旧 vs 新的性能/成本数据</td><td>docs/ 目录</td></tr></tbody></table><hr><h2 id="_7-核心原则" tabindex="-1">7. 核心原则 <a class="header-anchor" href="#_7-核心原则" aria-label="Permalink to &quot;7. 核心原则&quot;">​</a></h2><ol><li><strong>先跑起来，再优化</strong> — 可演示的 DEMO 比完美的架构重要 100 倍</li><li><strong>数据说话</strong> — 没有数据对比的架构都是吹牛逼</li><li><strong>可迁移</strong> — 嵌入式→工作站→K8s，同一套代码，只换配置</li><li><strong>可观测性标配</strong> — 没有监控的分布式系统等于盲人摸象</li><li><strong>CI/CD 自动化</strong> — 一键部署，不需要手动操作</li></ol>`,33)])])}const b=s(d,[["render",r]]);export{g as __pageData,b as default};
